import React, {useState} from 'react';
import { uparrow } from './svgs/uparrow.svg';

const ScrollButton = () =>{
const [visible, setVisible] = useState(false)
const toggleVisible = () => {
	const scrolled = document.documentElement.scrollTop;
	if (scrolled > 300){
		setVisible(true)
	}
	else {
		setVisible(false)
	}
};

const scrollToTop = () =>{
	window.scrollTo({
	top: 0,
	behavior: 'smooth'
	});
};

window.addEventListener('scroll', toggleVisible);

return (
	<button className="scroll-top" onClick={scrollToTop} style={{display: visible ? 'inline' : 'none'}}>
		<svg height="32px" id="Layer_1" version="1.1" viewBox="0 0 32 32" width="32px"><path d="M18.221,7.206l9.585,9.585c0.879,0.879,0.879,2.317,0,3.195l-0.8,0.801c-0.877,0.878-2.316,0.878-3.194,0  l-7.315-7.315l-7.315,7.315c-0.878,0.878-2.317,0.878-3.194,0l-0.8-0.801c-0.879-0.878-0.879-2.316,0-3.195l9.587-9.585  c0.471-0.472,1.103-0.682,1.723-0.647C17.115,6.524,17.748,6.734,18.221,7.206z" fill="#515151"/></svg>
	</button>
);
}

export default ScrollButton;
